[{"id": "call_j6fdzbzp", "function": {"index": 0, "name": "write_file", "arguments": {"content": "def read_settings(text):
    settings = {}
    for line in text.splitlines():
        stripped_line = line.strip()

        if not stripped_line or stripped_line.startswith('#'):
            continue

        if '=' not in stripped_line:
            raise ValueError("Malformed line: missing '='")

        parts = stripped_line.split('=', 1)
        if len(parts) != 2:
            # Should not happen if '=' is in stripped_line, but good practice
            raise ValueError("Malformed line")

        key = parts[0].strip()
        value = parts[1].strip()

        if key in settings:
            raise ValueError(f"Duplicate key found: {key}")

        settings[key] = value

    # Check for required keys
    required_keys = ['endpoint', 'enabled']
    for key in required_keys:
        if key not in settings:
            raise ValueError(f"Missing required key: {key}")

    # Process 'enabled' value to boolean
    if 'enabled' in settings:
        enabled_str = settings['enabled'].lower() # Already stripped when reading
        if enabled_str == 'true':
            settings['enabled'] = True
        elif enabled_str == 'false':
            settings['enabled'] = False
        else:
            raise ValueError(f"Invalid value for enabled: {settings['enabled']}")

    return settings
